class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None

    def insert(self, data):
        new_node = Node(data)
        new_node.next = self.next
        self.next = new_node
        return new_node

    def delete(self):
        if self.next is None:
            return None
        deleted = self.next
        self.next = deleted.next
        return deleted.data


class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def delete(self, data):
        if self.head is None:
            return False
        if self.head.data == data:
            self.head = self.head.next
            return True
        current = self.head
        while current.next:
            if current.next.data == data:
                current.delete()
                return True
            current = current.next
        return False

