from bisect import bisect_left

def lengthOfLIS(nums):
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def numIslands(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "1":
                count += 1
                grid[r][c] = "0"
                stack = [(r, c)]

                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == "1":
                            grid[nx][ny] = "0"
                            stack.append((nx, ny))

    return count

def findCheapestPrice(n, flights, src, dst, k):
    INF = float("inf")
    prices = [INF] * n
    prices[src] = 0

    for _ in range(k + 1):
        next_prices = prices[:]
        for u, v, p in flights:
            if prices[u] != INF:
                candidate = prices[u] + p
                if candidate < next_prices[v]:
                    next_prices[v] = candidate
        prices = next_prices

    return prices[dst] if prices[dst] != INF else -1

def maxProfitWithCooldown(prices):
    rest, hold, sold = 0, -float('inf'), -float('inf')
    for price in prices:
        rest, hold, sold = max(rest, sold), max(hold, rest - price), hold + price
    return max(rest, sold)

def coinChange(coins, amount):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)
    return -1 if dp[amount] > amount else dp[amount]

