        return safety_stock
    if lead_time >= len(daily_sales):
        max_window = sum(daily_sales)
    else:
        max_window = max(sum(daily_sales[i:i + lead_time]) for i in range(len(daily_sales) - lead_time + 1))
    return max_window + safety_stock

