        self.match = match
        self.calc = calc


FEE_RULES = [
    Rule(match=lambda w, d: True, calc=lambda w, d: w * 2),
    Rule(match=lambda w, d: True, calc=lambda w, d: d * 0.5),
    Rule(match=lambda w, d: w > 5, calc=lambda w, d: (w - 5) * 3),
    Rule(match=lambda w, d: d > 100, calc=lambda w, d: 20),
]


