def approach_a(p, et_c, d, r):
    if p > 1:
        p = p / 100
    I = 100 * (1 - p) + et_c * d - r
    return max(0, I)


def approach_b(p, et_c, d, r, daily_rain=None):
    if p > 1:
        p = p / 100
    W = p * 100

    if daily_rain is None:
        daily_rain = [r / d] * d
    else:
        if len(daily_rain) < d:
            daily_rain.extend([0] * (d - len(daily_rain)))

    for i in range(d):
        W = W - et_c
        if W < 0:
            W = 0
        W += daily_rain[i]
        if W > 100:
            W = 100

    I = 100 - W
    return max(0, I)

