def is_valid_isbn10(isbn):
    isbn = isbn.replace('-', '').replace(' ', '')
    if len(isbn) != 10:
        return False
    for c in isbn[:9]:
        if c not in '0123456789':
            return False
    if isbn[9] not in '0123456789Xx':
        return False

    total = 0
    for i in range(10):
        c = isbn[i]
        val = 10 if c in 'Xx' else int(c)
        total += (10 - i) * val

    return total % 11 == 0

