class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False


def extract_unique_words_b(sentence):
    root = TrieNode()
    cur = []
    for ch in sentence + ' ':
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
            cur.append(ch.lower())
        elif cur:
            node = root
            for c in cur:
                node = node.children.setdefault(c, TrieNode())
            node.is_word = True
            cur = []

    result = []

    def dfs(node, path):
        if node.is_word:
            result.append(path)
        for c in sorted(node.children):
            dfs(node.children[c], path + c)

    dfs(root, '')
    return result

