def roman_to_int_A(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    n = len(s)
    for i, ch in enumerate(s):
        val = values[ch]
        if i + 1 < n and val < values[s[i + 1]]:
            total -= val
        else:
            total += val
    return total

def roman_to_int_B(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    specials = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i + 1 < n and s[i:i + 2] in specials:
            total += specials[s[i:i + 2]]
            i += 2
        else:
            total += values[s[i]]
            i += 1
    return total

def sum_weekend_high_value_transactions(transactions):
    import re
    from datetime import date

    total = 0
    for date_str, amount in transactions:
        # 检查日期格式
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_str):
            continue

        # 检查是否为真实日期
        try:
            dt = date.fromisoformat(date_str)
        except ValueError:
            continue

        # 检查是否周末且金额超过1000
        if dt.weekday() >= 5 and amount > 1000:
            total += amount

    return total

