def is_phone_b(s: str) -> bool:
    count = 0
    first = None
    second = None
    for ch in s:
        if ch.isspace() or ch == '-':
            continue
        if not ch.isdigit():
            return False
        if count == 0:
            first = ch
        elif count == 1:
            second = ch
        count += 1
        if count > 11:
            return False
    return (
        count == 11
        and first == '1'
        and second is not None
        and '3' <= second <= '9'
    )

def most_frequent_order(orders):
    if not orders:
        return None
    count = {}
    for order in orders:
        count[order] = count.get(order, 0) + 1
    max_count = max(count.values())
    return min((order for order, c in count.items() if c == max_count), key=lambda x: int(x))

