def has_approx_match_scan(S, P):
    N = len(S)
    L = len(P)
    for i in range(N - L + 1):
        mismatch = 0
        for j in range(L):
            if S[i + j] != P[j]:
                mismatch += 1
                if mismatch > 1:
                    break
        if mismatch <= 1:
            return True
    return False


def has_approx_match_kmer(S, P):
    N = len(S)
    L = len(P)

    kmer_set = set()
    for i in range(N - L + 1):
        kmer_set.add(S[i:i + L])

    if P in kmer_set:
        return True

    for j in range(L):
        for b in 'ACGT':
            if b != P[j]:
                candidate = P[:j] + b + P[j + 1:]
                if candidate in kmer_set:
                    return True

    return False

