        return False
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        return False
    if any(n < 0 or n > 255 for n in nums):
        return False
    a, b, _, _ = nums
    if a == 10:
        return True
    if a == 172 and 16 <= b <= 31:
        return True
    if a == 192 and b == 168:
        return True
    return False


def ip_to_int(ip):
    parts = ip.split('.')
    if len(parts) != 4:
        return None
    try:
        nums = [int(p) for p in parts]
    except ValueError:
        return None
    if any(n < 0 or n > 255 for n in nums):
        return None
    return (nums[0] << 24) | (nums[1] << 16) | (nums[2] << 8) | nums[3]


def is_private_ip_by_mask(ip):
    ip_int = ip_to_int(ip)
    if ip_int is None:
        return False
    private_networks = [
        (0x0A000000, 0xFF000000),  # 10.0.0.0/8
        (0xAC100000, 0xFFF00000),  # 172.16.0.0/12
        (0xC0A80000, 0xFFFF0000),  # 192.168.0.0/16
    ]
    for network, mask in private_networks:
        if (ip_int & mask) == network:
            return True
    return False

