            arr[k] = x
            k += 1
    return arr[:k]

def remove_duplicates_inplace(arr):
    k = 0
    for i in range(len(arr)):
        duplicate = False
        for j in range(k):
            if arr[j] == arr[i]:
                duplicate = True
                break
        if not duplicate:
            arr[k] = arr[i]
            k += 1
    return arr[:k]

