def longest_heatwave_b(temperatures):
    def helper(l, r):
        if l > r:
            return 0
        if l == r:
            return 1 if temperatures[l] > 35 else 0

        mid = (l + r) // 2

        left_ans = helper(l, mid)
        right_ans = helper(mid + 1, r)

        left_cnt = 0
        i = mid
        while i >= l and temperatures[i] > 35:
            left_cnt += 1
            i -= 1

        right_cnt = 0
        j = mid + 1
        while j <= r and temperatures[j] > 35:
            right_cnt += 1
            j += 1

