def extract_unique_words_with_trie(text):
    import re
    root = {}
    for word in re.findall(r'[a-z]+', text.lower()):
        node = root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        node['$'] = True

    result = []

    def dfs(node, prefix):
        if '$' in node:
            result.append(prefix)
        for ch in sorted(k for k in node if k != '$'):
            dfs(node[ch], prefix + ch)

    dfs(root, '')
    return result

