def longest_consecutive_rise_divide(temps):
    if not temps:
        return 0
    def solve(l, r):
        if l == r:
            return 1
        mid = (l + r) // 2
        left_ans = solve(l, mid)
        right_ans = solve(mid + 1, r)
        cross = 0
        if temps[mid] < temps[mid + 1]:
            left_len = 1
            k = mid - 1
            while k >= l and temps[k] < temps[k + 1]:
                left_len += 1
                k -= 1
            right_len = 1
            k = mid + 2
            while k <= r and temps[k - 1] < temps[k]:
                right_len += 1
                k += 1
            cross = left_len + right_len
        return max(left_ans, right_ans, cross)
    return solve(0, len(temps) - 1)

