    pattern = r'^((25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$'
    return re.fullmatch(pattern, s) is not None


def is_valid_ipv4_split(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if any(c not in '0123456789' for c in part):
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not (0 <= int(part) <= 255):
            return False
    return True

def is_secure_password_loop(password):
    length = 0
    has_alpha = False
    has_digit = False
    for ch in password:
        length += 1
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
            has_alpha = True
        if ch.isdigit():
            has_digit = True
    return length >= 8 and has_alpha and has_digit

def is_secure_password_regex(password):
    import re
    return bool(re.match(r'^(?=.*[A-Za-z])(?=.*\d).{8,}$', password))

def is_matched(s):
    stack = []
    for ch in s:
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def are_brackets_balanced(text: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    left = set(pairs.values())

    for ch in text:
        if ch in left:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False

    return not stack

def is_palindrome_permutation(s: str) -> bool:
    mask = 0
    for ch in s:
        if 'a' <= ch <= 'z':
            bit = ord(ch) - ord('a')
        elif 'A' <= ch <= 'Z':
            bit = ord(ch) - ord('A')
        else:
            continue
        mask ^= 1 << bit
    return (mask & (mask - 1)) == 0

