def is_valid_date_A(date_str: str) -> bool:
    import re
    from datetime import date

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str):
        return False

    try:
        date.fromisoformat(date_str)
        return True
    except ValueError:
        return False


def is_leap_year(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def is_valid_date_B(date_str: str) -> bool:
    if len(date_str) != 10 or date_str[4] != "-" or date_str[7] != "-":
        return False

    year_s = date_str[:4]
    month_s = date_str[5:7]
    day_s = date_str[8:10]

    if not (year_s.isdigit() and month_s.isdigit() and day_s.isdigit()):
        return False

    year = int(year_s)
    month = int(month_s)
    day = int(day_s)

    if not (1 <= year <= 9999):
        return False
    if not (1 <= month <= 12):
        return False

    month_days = [
        31,
        29 if is_leap_year(year) else 28,
        31, 30, 31, 30, 31, 31, 30, 31, 30, 31
    ]

    return 1 <= day <= month_days[month - 1]

import math

def calculate_shipping_fee(weight: float, distance: float) -> float:
    weight_fee = 10 + max(0, math.ceil(weight) - 1) * 3
    if distance <= 10:
        distance_fee = 0
    elif distance <= 50:
        distance_fee = 5
    else:
        distance_fee = 15
    return weight_fee + distance_fee

from datetime import date

def check_by_date(text):
    prev = None
    for line in text.strip().splitlines():
        if not line.strip():
            continue
        date_str = line.split()[0]
        try:
            d = date.fromisoformat(date_str)
        except ValueError:
            return False
        if prev is not None and d <= prev:
            return False
        prev = d
    return True

from datetime import datetime

def convert_with_datetime(time_str):
    dt = datetime.strptime(time_str, "%H:%M")
    return dt.strftime("%I:%M %p").lstrip("0")

def convert_manually(time_str):
    hour_str, minute_str = time_str.split(":")
    hour = int(hour_str)
    minute = int(minute_str)
    period = "AM" if hour < 12 else "PM"
    hour12 = hour % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d} {period}"

def is_private_ip(ip):
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    a, b = int(parts[0]), int(parts[1])
    if a == 10:
        return True
    if a == 172 and 16 <= b <= 31:
        return True
    if a == 192 and b == 168:
        return True
    return False

