def check_brackets_by_collapse(s):
    b = ''.join(ch for ch in s if ch in '()[]{}')
    while True:
        new_b = b.replace('()', '').replace('[]', '').replace('{}', '')
        if new_b == b:
            break
        b = new_b
    return b == ''

