def can_form_palindrome(s: str) -> bool:
    odd_chars = set()
    for ch in s:
        if ch in odd_chars:
            odd_chars.remove(ch)
        else:
            odd_chars.add(ch)
    return len(odd_chars) <= 1

def calculate_bill_A(monthly_usage):
    if monthly_usage <= 200:
        return monthly_usage * 0.5
    elif monthly_usage <= 400:
        return 200 * 0.5 + (monthly_usage - 200) * 0.6
    else:
        return 200 * 0.5 + 200 * 0.6 + (monthly_usage - 400) * 0.8

def calculate_bill_B(monthly_usage):
    tier1 = min(monthly_usage, 200)
    tier2 = min(max(monthly_usage - 200, 0), 200)
    tier3 = max(monthly_usage - 400, 0)
    return tier1 * 0.5 + tier2 * 0.6 + tier3 * 0.8

