def roman_to_int(s: str) -> int:
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        cur = values[ch]
        if cur < prev:
            total -= cur
        else:
            total += cur
        prev = cur
    return total

def longest_over_20(temperatures):
    cur = 0
    best = 0
    for t in temperatures:
        if t > 20:
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 0
    return best

