def has_duplicates(lst):
    seen = set()
    for item in lst:
        if item in seen:
            return True
        seen.add(item)
    return False

def average_by_sum(nums):
    """通过 sum/len 计算平均值。"""
    if not nums:
        raise ValueError("列表不能为空")
    return sum(nums) / len(nums)


def average_by_welford(nums):
    """通过 Welford 在线算法逐步更新平均值。"""
    if not nums:
        raise ValueError("列表不能为空")
    mean = 0.0
    for count, x in enumerate(nums, 1):
        mean += (x - mean) / count
    return mean

def average_a(numbers):
    if not numbers:
        raise ValueError("列表不能为空")
    return sum(numbers) / len(numbers)

def average_b(numbers):
    it = iter(numbers)
    try:
        mean = next(it)
    except StopIteration:
        raise ValueError("列表不能为空") from None
    for i, x in enumerate(it, start=2):
        mean += (x - mean) / i
    return mean
